SELECT
    pu.programa_unico_id AS cod_unico,
    pu.codigo AS cod_academico,
    c.nombre AS tipo,
    COALESCE(MAX(CASE WHEN mpu.numero = 1 THEN mpu.nombre END), '-') AS Modulo_1,
    COALESCE(MAX(CASE WHEN mpu.numero = 2 THEN mpu.nombre END), '-') AS Modulo_2,
    COALESCE(MAX(CASE WHEN mpu.numero = 3 THEN mpu.nombre END), '-') AS Modulo_3,
    COALESCE(MAX(CASE WHEN mpu.numero = 4 THEN mpu.nombre END), '-') AS Modulo_4,
    COALESCE(MAX(CASE WHEN mpu.numero = 5 THEN mpu.nombre END), '-') AS Modulo_5,
    COALESCE(MAX(CASE WHEN mpu.numero = 6 THEN mpu.nombre END), '-') AS Modulo_6,
    COALESCE(MAX(CASE WHEN mpu.numero = 7 THEN mpu.nombre END), '-') AS Modulo_7,
    COALESCE(MAX(CASE WHEN mpu.numero = 8 THEN mpu.nombre END), '-') AS Modulo_8,
    COALESCE(MAX(CASE WHEN mpu.numero = 9 THEN mpu.nombre END), '-') AS Modulo_9,
    COALESCE(MAX(CASE WHEN mpu.numero = 10 THEN mpu.nombre END), '-') AS Modulo_10,
    COALESCE(MAX(CASE WHEN mpu.numero = 11 THEN mpu.nombre END), '-') AS Modulo_11,
    COALESCE(MAX(CASE WHEN mpu.numero = 12 THEN mpu.nombre END), '-') AS Modulo_12,
    COALESCE(MAX(CASE WHEN mpu.numero = 13 THEN mpu.nombre END), '-') AS Modulo_13,
    COALESCE(MAX(CASE WHEN mpu.numero = 14 THEN mpu.nombre END), '-') AS Modulo_14,
    COALESCE(MAX(CASE WHEN mpu.numero = 15 THEN mpu.nombre END), '-') AS Modulo_15,
    COALESCE(MAX(CASE WHEN mpu.numero = 16 THEN mpu.nombre END), '-') AS Modulo_16,
    COALESCE(MAX(CASE WHEN mpu.numero = 17 THEN mpu.nombre END), '-') AS Modulo_17,
    COALESCE(MAX(CASE WHEN mpu.numero = 18 THEN mpu.nombre END), '-') AS Modulo_18
FROM programa_universidad pu
LEFT JOIN modulo_programa_universidad mpu ON pu.id = mpu.programa_universidad_id
LEFT JOIN programas p ON pu.id = p.programa_universidad_id 
LEFT JOIN postgrados p2 ON p.idpostgrado = p2.id  
LEFT JOIN categorias c ON p2.idcategoria = c.id
